        if (!k->cfmt[i]) continue;
        int l = merged ? k->lmap[i] : i;
        if (l == 0xff || (fs->rf.color_known && !(fs->rf.color_mask >> l & 1))) continue;   // an output the shader does not write
        if (!mtl_fmt_uint((MTLPixelFormat)k->cfmt[i])) return 0;
