    uint32_t n = SHARED_IB_N; uint32_t *ix = malloc(n * 6 * 4);
    for (uint32_t q = 0; q < n; q++) { uint32_t b = q * 4; uint32_t v[6] = {b, b + 1, b + 2, b, b + 2, b + 3}; memcpy(ix + q * 6, v, 24); }
