            aj[na++] = (ajob){rec, ag + 32 * (uint64_t)i, (uint32_t)e->prim, e->ixlen / 4}; e->args = ag + 32 * (uint64_t)i;
        } else {   // DrawElementsIndirect: expanded into a 32-bit list, one thread per output index
